drills.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  01 · allocation-free date parsing★★★ core
//  concepts: ReadOnlySpan<char> · slicing · validation
// ─────────────────────────────────────────────────────────────────────────
//
//  Slice the span and parse the slices: no temporary strings.

using static Bootcamp.Check;

bool TryParseIsoDate(ReadOnlySpan<char> s, out int year, out int month, out int day)
{
    year = month = day = 0;
    if (s.Length != 10 || s[4] != '-' || s[7] != '-') return false;
    for (var i = 0; i < 10; i++)
    {
        if (i == 4 || i == 7) continue;
        if (s[i] < '0' || s[i] > '9') return false;
    }
    var y = int.Parse(s[..4]);
    var m = int.Parse(s.Slice(5, 2));
    var d = int.Parse(s.Slice(8, 2));
    if (y < 1 || m is < 1 or > 12 || d < 1 || d > DateTime.DaysInMonth(y, m)) return false;
    (year, month, day) = (y, m, d);
    return true;
}

drills.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("a valid date parses", () =>
{
    Ok(TryParseIsoDate("2026-11-04", out var y, out var m, out var d), "should parse");
    Eq((y, m, d), (2026, 11, 4));
});

Test("leap days follow the calendar", () =>
{
    Ok(TryParseIsoDate("2024-02-29", out _, out _, out _), "2024 is a leap year");
    Ok(!TryParseIsoDate("2023-02-29", out _, out _, out _), "2023 is not");
    Ok(!TryParseIsoDate("2026-04-31", out _, out _, out _), "April has 30 days");
});

Test("wrong shapes are rejected", () =>
{
    foreach (var bad in new[] { "2026-1-04", "2026/11/04", "2026-11-04T", "20261104", "2026-13-01", "2026-00-10", "2026-11-00", "+026-11-04", "2026-1a-04", "" })
    {
        Ok(!TryParseIsoDate(bad, out var y, out _, out _), bad);
        Eq(y, 0);
    }
});

Test("parsing allocates nothing (boundary)", () =>
{
    var text = "2026-11-04 rest of the log line".AsSpan(0, 10).ToArray();
    TryParseIsoDate(text, out _, out _, out _);
    var before = GC.GetAllocatedBytesForCurrentThread();
    for (var i = 0; i < 1000; i++) TryParseIsoDate(text, out _, out _, out _);
    var allocated = GC.GetAllocatedBytesForCurrentThread() - before;
    Ok(allocated < 1000, $"allocated {allocated} bytes for 1000 parses");
});

drills.explanation:
Check the shape character by character, then let `int.Parse` read each slice of the span directly:

```csharp
if (s.Length != 10 || s[4] != '-' || s[7] != '-') return false;
// ... every other character must be an ASCII digit ...
var y = int.Parse(s[..4]);
var m = int.Parse(s.Slice(5, 2));
var d = int.Parse(s.Slice(8, 2));
if (y < 1 || m is < 1 or > 12 || d < 1 || d > DateTime.DaysInMonth(y, m)) return false;
```

The digit check comes first so `int.Parse` never sees a sign or a letter and never throws. Dropping that loop fails "wrong shapes are rejected": `int.Parse` accepts `+026` as the year 26 and throws on `1a`. `DateTime.DaysInMonth` knows the leap years, so no hand-written rule is needed. A version that calls `s.ToString()` and parses substrings gives the same answers but allocates four strings per call, about 144 KB for the 1,000 parses of "parsing allocates nothing (boundary)", which therefore fails.

